        "translation": "Không sao đâu, đang cắm ngay trên ổ điện trên bàn mình đó, cậu cứ lấy xài tự nhiên nha.",
        "grammarNote": "插座 (chāzuò): Ổ cắm điện; 直接 (zhíjiē): Trực tiếp, cứ tự nhiên."
