        "id": "zh-hsk2-06-s2",
        "text": "请出示您的护照，并在这张换汇申请单上签个名字。",
        "phonetic": "Qǐng chūshì nín de hùzhào, bìng zài zhè zhāng huànhuì shēnqǐngdān shang qiān ge míngzi.",
        "translation": "Xin vui lòng xuất trình hộ chiếu của quý khách, và ký tên lên tờ đơn xin đổi ngoại tệ này.",
