        "phonetic": "Liǎngbiān tuī duǎn, liúhǎi liú dào méimao shàngmian yìdiǎnr jiù kěyǐ le.",
        "translation": "Hai bên ủi ngắn, tóc mái để tới phía trên lông mày một tí là được rồi ạ.",
        "grammarNote": "刘海 (liúhǎi): Tóc mái; 眉毛 (méimao): Lông mày; ...就可以了: ...là được rồi."
