        "translation": "Dạo này tôi thường xuyên thức khuya ôn thi, quầng thâm mắt đều lộ rõ cả rồi.",
        "grammarNote": "熬夜 (áoyè): Thức khuya; 黑眼圈 (hēiyǎnquān): Quầng thâm mắt."
